const parseNode = $('Parse Players').item.json;
const player1 = parseNode.player1 || 'Player 1';
const player2 = parseNode.player2 || 'Player 2';
const surface = parseNode.surface || 'Unknown';
const tournament = parseNode.tournament || 'ATP/WTA Tour';

let scoreboard = '{}';
let news = '[]';
let odds = '[]';

try { scoreboard = JSON.stringify($input.all()[0]?.json ?? {}); } catch(_) {}
try { news = JSON.stringify($input.all()[1]?.json ?? {}); } catch(_) {}
try { odds = JSON.stringify($input.all()[2]?.json ?? []); } catch(_) {}

// Parse odds for the matchup
let oddsPayload = 'No odds available';
try {
  const oddsData = JSON.parse(odds);
  if (Array.isArray(oddsData) && oddsData.length > 0) {
    const p1lower = player1.toLowerCase();
    const p2lower = player2.toLowerCase();
    const match = oddsData.find(g => {
      const a = (g.away_team || '').toLowerCase();
      const h = (g.home_team || '').toLowerCase();
      return (a.includes(p1lower.split(' ').pop()) || h.includes(p1lower.split(' ').pop())) ||
             (a.includes(p2lower.split(' ').pop()) || h.includes(p2lower.split(' ').pop()));
    });
    if (match) {
      const bm = match.bookmakers?.[0];
      const h2h = bm?.markets?.find(m => m.key === 'h2h');
      if (h2h?.outcomes) {
        oddsPayload = h2h.outcomes.map(o => `${o.name}: ${o.price > 0 ? '+' : ''}${o.price}`).join(' | ');
      }
    }
  }
} catch(_) {}

return [{
  json: {
    player1,
    player2,
    surface,
    tournament,
    espn_scoreboard: scoreboard.slice(0, 3000),
    espn_news: news.slice(0, 2000),
    odds_payload: oddsPayload
  }
}];
